import{_ as s,l as o,o as r,c as i,v as m,p as h,x as n,d as t,i as d,S as p,b as e}from"./chunks/framework.InCnrqk-.js";const v=JSON.parse('{"title":"Universal Transformer 与循环深度","description":"","frontmatter":{"title":"Universal Transformer 与循环深度","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/universal-transformer-recurrence.md","filePath":"llm/universal-transformer-recurrence.md","lastUpdated":1789023840000}'),T={name:"llm/universal-transformer-recurrence.md"};function f(u,a,c,A,C,E){const l=o("Mermaid");return r(),i("div",null,[a[1]||(a[1]=m('<h1 id="universal-transformer-与循环深度" tabindex="-1">Universal Transformer 与循环深度 <a class="header-anchor" href="#universal-transformer-与循环深度" aria-label="Permalink to &quot;Universal Transformer 与循环深度&quot;">​</a></h1><div class="epigraph"><p>与其堆互不共享的层，不如反复应用同一块 Transformer，并用自适应计算决定每步停在哪一跳。</p><footer>—— Dehghani et al., Universal Transformers, ICLR 2019</footer></div><p><a href="/llm/attention-head-roles">上一课</a>把功能放在「第 \\(\\ell\\) 层第 \\(h\\) 头」。加深模型的默认办法是再复制一组不共享的参数，深度与参数量绑死。本课把深度改成<strong>对同一块的循环次数</strong>：参数按块计，计算按步计。Dehghani 等人的 Universal Transformer 还加上每位置的 ACT（自适应计算时间）。后课 looped Transformer 会把这件事收到更干净的「固定循环次数」；本课先保留 ACT 这条原论文设定。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>加层能叠功能，但第 1 层与第 24 层各养一套权重，浅层的注意力电路无法在深层以同一套参数复用。算法类任务往往需要「同一规则应用许多次」，参数复制不是规则复用。缺口是：把 Transformer 块当成 RNN 的转移函数，序列长度仍由注意力处理，<strong>深度变成时间维上的迭代</strong>。</p><p>这与 <a href="/llm/albert-param-sharing">ALBERT</a> 的跨层共享相近，但 Universal Transformer 明确把迭代次数当成可学习或自适应的计算预算，而不是训练时绑死 \\(L\\) 再微调。ALBERT 课在后，因为先要有循环深度这个概念，再谈「为了参数量去共享」。</p><p><span class="marginnote">这里的循环不是沿 token 的 RNN，沿 token 仍是并行注意力。循环轴是块的应用次数，对每个位置可以不同（ACT）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>共享块 \\(F_\\theta\\)，状态 \\(h^{(0)}\\) 为嵌入（加位置）。\\(h^{(t+1)}=h^{(t)}+F_\\theta(h^{(t)})\\)，注意力在当前 \\(t\\) 的整段序列上算，仍是双向或因果，取决于任务。位置编码在每次迭代可以重新加入，以免迭代把绝对位置冲掉。</p><p>ACT：每个位置输出一个停机标量，用 Graves 的自适应计算时间累加，直到质量超过阈值或达到最大步数 \\(T_{\\max}\\)。未停机的位置继续迭代；已停机的位置拷贝状态。训练用停机损失防止所有位置跑满 \\(T_{\\max}\\)。</p><h3 id="与普通-层的计算对比" tabindex="-1">与普通 \\(L\\) 层的计算对比 <a class="header-anchor" href="#与普通-层的计算对比" aria-label="Permalink to &quot;与普通 $L$ 层的计算对比&quot;">​</a></h3><p>固定 \\(T=L\\) 且无 ACT 时，FLOPs 与 \\(L\\) 层不共享模型同阶，参数却只有一块。收益在参数与规则复用，不在单次前向变便宜。ACT 才可能让简单 token 早停、难 token 多迭代，这是后课早退要接的线。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同一套 \\(W^Q,W^K,W^V\\) 在不同迭代看见的残差流不同，头的功能随 \\(t\\) 变，而不是随层号变。这要求块足够通用，能在「先做局部混合、再做长程检索」之间切换——功能分化从空间上的不同层，改成时间上的不同步。若块太弱，迭代只是把同一种错误重复 \\(T\\) 次。</p><p>ACT 让计算分配跟内容走：标点可能一步够，嵌套结构要多步。停机门若学崩，要么全早停（欠计算），要么全满转（退回固定深度）。与后课固定 \\(T\\) 的 looped 相比，ACT 把预算当成每位置的隐变量；与后课早退相比，这里的出口在共享块内部，而不是在互不共享的层号上。</p><p><span class="marginnote">推理延迟由最慢位置的迭代次数决定，除非实现真正跳过已停位置。批里一个难 token 会拖住整步，这是自适应深度的系统税。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>共享块训练更难：深度等效很大时，梯度穿过 \\(T\\) 次同一参数，与 RNN 的梯度问题同类，需要残差与初始化约束。Universal Transformer 原文在算法与小规模翻译上示意，不是直接替代今日千亿解码器的配方。下一课去掉 ACT，只保留固定循环，便于与现代「looped」工作对齐。不要把本课写成已经解决了长推理链——那是提示与推理课的对象，这里只改块的复用。</p>',18)),(r(),h(p,null,{default:n(()=>[d(l,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20H0%5B%22%E5%B5%8C%E5%85%A5%20h0%22%5D%20--%3E%20F%5B%22%E5%85%B1%E4%BA%AB%E5%9D%97%20F_theta%22%5D%0A%20%20F%20--%3E%20ACT%5B%22%E6%AF%8F%E4%BD%8D%E7%BD%AE%E5%81%9C%E6%9C%BA%E9%97%A8%22%5D%0A%20%20ACT%20--%3E%7C%22%E6%9C%AA%E5%81%9C%22%7C%20F%0A%20%20ACT%20--%3E%7C%22%E5%B7%B2%E5%81%9C%22%7C%20Out%5B%22%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[t("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"Universal Transformer 沿深度循环同一块，参数与层数解绑；注意力仍沿序列。"),e("li",null,"ACT 让每位置的迭代次数成为计算预算，停机失败则退回固定 \\(T_{\\max}\\)。"),e("li",null,"功能随迭代步变化，要求块通用；弱块迭代无益。"),e("li",null,"批延迟由最慢位置决定；训练有 RNN 式梯度风险。"),e("li",null,"出处：Dehghani et al., ICLR 2019；ACT 见 Graves, 2016。")],-1))])}const B=s(T,[["render",f]]);export{v as __pageData,B as default};
